<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_reports');$error='';$from=request_string($_GET,'from')?:date('Y-m-01');$to=request_string($_GET,'to')?:date('Y-m-d');$department=positive_id($_GET,'department_id');
try{date_value($from,true);date_value($to,true);if($from>$to)throw new InvalidArgumentException('Select an end date on or after the start date.');}catch(InvalidArgumentException $e){$error=$e->getMessage();$from=date('Y-m-01');$to=date('Y-m-d');}
$scope=$department?' WHERE s.department_id=?':'';$sp=$department?[$department]:[];
$staff=query("SELECT COUNT(*) total,COALESCE(SUM(employment_status='active'),0) active,COALESCE(SUM(employment_status='new'),0) new,COALESCE(SUM(employment_status='exited'),0) exited FROM staff_directory s".$scope,$sp)->fetch();
$joined=(int)query('SELECT COUNT(*) FROM staff_directory s'.($scope?:' WHERE 1=1').' AND start_date BETWEEN ? AND ?',array_merge($sp,[$from,$to]))->fetchColumn();
$exited=(int)query('SELECT COUNT(*) FROM staff_directory s'.($scope?:' WHERE 1=1').' AND exit_date BETWEEN ? AND ?',array_merge($sp,[$from,$to]))->fetchColumn();
[$tw,$tp]=ticket_filter(['from'=>$from,'to'=>$to,'department_id'=>(string)$department],$user);
$tickets=query('SELECT t.status,COUNT(*) total FROM tickets t'.$tw.' GROUP BY t.status',$tp)->fetchAll();
$teams=query("SELECT d.name department_name,s.team_label,COUNT(*) total,SUM(s.employment_status='active') active FROM staff_directory s JOIN departments d ON d.id=s.department_id".$scope.' GROUP BY d.name,s.team_label ORDER BY d.name,s.team_label',$sp)->fetchAll();
$leaders=query('SELECT u.full_name,COUNT(*) total FROM staff_directory s JOIN users u ON u.id=s.tl_id'.($scope?:' WHERE 1=1')." AND s.employment_status<>'exited' GROUP BY u.id,u.full_name ORDER BY total DESC,u.full_name",$sp)->fetchAll();
page_start('Reports & exports',$user);?><div class="section-head"><div><h2>People and service, in perspective</h2><p class="muted">Review starters, exits and ticket activity for your selected period.</p></div></div><?php error_notice($error);?><section class="panel"><form method="get" class="filter-grid"><label>Period from<input type="date" name="from" value="<?=e($from)?>" required></label><label>Period to<input type="date" name="to" value="<?=e($to)?>" required></label><label>Current department<select name="department_id"><option value="">All departments</option><?php options(active_departments(),(string)$department);?></select></label><div class="actions"><button class="button">Update report</button><a class="button button-secondary" href="reports.php">This month</a></div></form><div class="actions"><?php $args=['from'=>$from,'to'=>$to,'department_id'=>(string)$department];if(user_can('export_staff')):?><a class="button button-secondary" href="export.php?<?=e(http_build_query($args+['type'=>'report']))?>">Export report</a><a class="button button-secondary" href="export.php?<?=e(http_build_query(['type'=>'staff','department_id'=>(string)$department]))?>">Export current staff</a><a class="button button-secondary" href="export.php?<?=e(http_build_query($args+['type'=>'history']))?>">Export period history</a><?php endif;if(user_can('export_tickets')):?><a class="button button-secondary" href="export.php?<?=e(http_build_query($args+['type'=>'tickets']))?>">Export period tickets</a><?php endif;?></div></section><div class="metrics"><?php foreach([['Current active staff',$staff['active']],['Current new staff',$staff['new']],['Started in period',$joined],['Exited in period',$exited]] as [$label,$value]):?><div class="metric"><span class="metric-label"><?=$label?></span><strong><?=(int)$value?></strong></div><?php endforeach;?></div><div class="split"><section class="panel flush"><div class="panel-heading"><h2>Current departments & teams</h2></div><div class="table-wrap"><table><thead><tr><th>Department</th><th>Team</th><th>All staff</th><th>Active</th></tr></thead><tbody><?php foreach($teams as $team):?><tr><td><?=e($team['department_name'])?></td><td><?=e($team['team_label'])?></td><td><?=(int)$team['total']?></td><td><?=(int)$team['active']?></td></tr><?php endforeach;if(!$teams):?><tr><td colspan="4" class="empty">No employees in this scope.</td></tr><?php endif;?></tbody></table></div></section><section class="panel"><h2>Tickets created in period</h2><p class="muted">Grouped by their current status.</p><?php $sum=array_sum(array_column($tickets,'total'));foreach($tickets as $ticket):?><div class="section-head"><span><?=e(TICKET_STATUSES[$ticket['status']])?></span><strong><?=(int)$ticket['total']?></strong></div><div class="report-bar"><span style="width:<?=round(100*$ticket['total']/max(1,$sum))?>%"></span></div><?php endforeach;if(!$tickets):?><p class="muted">No tickets were created in this period.</p><?php endif;?></section></div><section class="panel"><h2>Current team leader assignments</h2><p class="muted">Active and new employees assigned to each TL.</p><div class="table-wrap"><table><thead><tr><th>Team leader</th><th>Assigned employees</th></tr></thead><tbody><?php foreach($leaders as $leader):?><tr><td><?=e($leader['full_name'])?></td><td><?=(int)$leader['total']?></td></tr><?php endforeach;if(!$leaders):?><tr><td colspan="2" class="empty">No team assignments.</td></tr><?php endif;?></tbody></table></div></section><?php page_end();
